mapper.select:
select distinct u.user_id, u.user_code, u.organization_id,o.organization_name, u.user_name, u.nick_name, u.user_type, u.dept,u.email, u.phonenumber, u.sex, u.password, u.status, u.del_flag, u.login_status, u.login_ip, u.login_date,u.create_by, u.create_time, u.update_by, u.update_time from sys_user u left join sys_user_role ur on u.user_id = ur.user_id left join sys_organization o on u.organization_id=o.organization_id where u.del_flag = '0'
AND u.organization_id=#{loginOrganization}
AND u.user_id = #{userId}
AND u.nick_name like concat('%', #{nickName}, '%')
AND u.user_name like concat('%', #{userName}, '%')
AND u.role_id = #{roleId}
AND ur.role_id in
#{value}
AND u.status = #{status}
AND u.organization_id in(select so.organization_id from sys_organization so where so.organization_name like concat('%', #{organizationName}, '%'))
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND date_format(u.create_time,'%Y-%m-%d') >= date_format(#{beginTime},'%Y-%m-%d')
AND date_format(u.create_time,'%Y-%m-%d') <= date_format(#{endTime},'%Y-%m-%d')
${params.dataScope} order by u.create_time desc

select authorization_member_limit - authorization_member_used
from sys_organization_authorization
where organization_id = #{organizationId}

mapper.update:
update sys_user
nick_name = #{nickName}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, role_id = #{roleId}, organization_id = #{organizationId}, dept = #{dept}, update_time = sysdate()
where user_id = #{userId}

update sys_user
set login_status = #{loginStatus},
    password=#{password}
where user_id = #{userId}

mapper.select:
select o.organization_id organizationId, o.organization_name organizationName,
case status when 1 then 1 else (case when date_format(a.expiration_time, '%y%m%d') >= date_format(now(), '%y%m%d') then 0 else 1 end) end state from sys_organization o join sys_organization_authorization a on o.organization_id = a.organization_id where o.del_flag = '0'
and o.organization_id = #{organizationId}
